/**
 * build-stamp.ts - write or check the handler build stamp (DEC-048 package 3.3).
 *
 * usage: build-stamp.ts [--check] [--dir <handler folder>]
 *
 * The stamp is `bundleDigest` of src/workbench/client.ts, imported (not re-implemented) so the two
 * can never disagree: sha1 over name, NUL, bytes, NUL of every `.c` file in the shipped handler
 * folder, sorted by name, with BUILD_STAMP_FILE (EMCP_WB_BuildStamp.c, the generated file itself)
 * left out, since a file cannot hold the digest of its own bytes. CRLF is read as LF, so an LF and
 * a CRLF checkout of the same commit get the same stamp.
 *
 * Default: writes `EMCP_WB_BuildStamp.c` holding one constant, EMCP_WB_BuildStamp.VALUE, which
 * EMCP_WB_Ping answers as `buildStamp`. --check: writes nothing; exit 1 when the file is missing
 * or its constant differs from the digest of the current bundle. Exit 2 on a usage error or an
 * unreadable bundle.
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parseArgs } from "node:util";
import { BUILD_STAMP_FILE, bundleDigest, bundledHandlerDir } from "../src/workbench/client.js";
import {
  EXIT_FAIL,
  EXIT_OK,
  EXIT_USAGE,
  PROCESS_IO,
  isMainModule,
  type Io,
} from "./census/cli-common.js";

const USAGE = "usage: build-stamp.ts [--check] [--dir <handler folder>]";

/** The generated Enforce source holding `digest`. */
export function stampSource(digest: string): string {
  return [
    "/**",
    ` * ${BUILD_STAMP_FILE} - GENERATED by scripts/build-stamp.ts; do not edit.`,
    " *",
    " * The digest of the handler set this bundle was built from (client.ts bundleDigest: every .c",
    " * file in this folder except this one). EMCP_WB_Ping answers it as buildStamp.",
    " */",
    "",
    "class EMCP_WB_BuildStamp",
    "{",
    `\tstatic const string VALUE = "${digest}";`,
    "}",
    "",
  ].join("\n");
}

/** The constant held by a generated stamp file's text, or null when there is none. */
export function readStamp(source: string): string | null {
  const m = /static const string VALUE = "([0-9a-f]*)";/.exec(source);
  return m ? m[1] : null;
}

export function run(argv: string[], io: Io = PROCESS_IO): number {
  let values: { check?: boolean; dir?: string };
  try {
    ({ values } = parseArgs({
      args: argv,
      options: { check: { type: "boolean" }, dir: { type: "string" } },
      strict: true,
      allowPositionals: false,
    }));
  } catch (e) {
    io.err(`${(e as Error).message}\n${USAGE}\n`);
    return EXIT_USAGE;
  }
  const dir = values.dir ?? bundledHandlerDir();
  const digest = bundleDigest(dir);
  if (!digest) {
    io.err(`no handler .c files readable in ${dir}\n`);
    return EXIT_USAGE;
  }
  const file = join(dir, BUILD_STAMP_FILE);
  if (values.check) {
    const stamp = existsSync(file) ? readStamp(readFileSync(file, "utf-8")) : null;
    if (stamp === digest) {
      io.out(`build stamp OK: ${digest}\n`);
      return EXIT_OK;
    }
    io.err(
      `build stamp STALE: ${BUILD_STAMP_FILE} holds ${stamp ?? "(none)"}, the bundle is ${digest}; run scripts/build-stamp.ts\n`,
    );
    return EXIT_FAIL;
  }
  writeFileSync(file, stampSource(digest), "utf-8");
  io.out(`wrote ${BUILD_STAMP_FILE}: ${digest}\n`);
  return EXIT_OK;
}

if (isMainModule(import.meta.url)) {
  process.exitCode = run(process.argv.slice(2));
}
